describe('Notification Bell Badge Count', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.login();
  });

  it('should display badge count on notification bell icon', () => {
    cy.get('[data-testid="notification-bell"]').should('be.visible');
    cy.get('[data-testid="notification-badge"]').should('be.visible');
    cy.get('[data-testid="notification-badge"]').should('contain', '3');
  });

  it('should update badge count when new notification arrives', () => {
    cy.get('[data-testid="notification-badge"]').should('contain', '3');
    cy.triggerNotification('test-notification');
    cy.get('[data-testid="notification-badge"]').should('contain', '4');
  });

  it('should hide badge when notification count is zero', () => {
    cy.clearAllNotifications();
    cy.get('[data-testid="notification-badge"]').should('not.exist');
  });

  it('should display correct badge count after reading notifications', () => {
    cy.get('[data-testid="notification-badge"]').should('contain', '3');
    cy.get('[data-testid="notification-bell"]').click();
    cy.get('[data-testid="notification-item"]').first().click();
    cy.get('[data-testid="notification-badge"]').should('contain', '2');
  });

  it('should handle large badge counts gracefully', () => {
    cy.addNotifications(99);
    cy.get('[data-testid="notification-badge"]').should('contain', '99');
    cy.addNotifications(1);
    cy.get('[data-testid="notification-badge"]').should('contain', '100');
  });
});
